/** Parts of the plan that are always on: the system depends on them (listed on the Features page, not switchable). */
export const ALWAYS_ON = [
    { n: 25, release: "1.8", name: "HTTPS on the hospital network", why: "Pharmacy PCs trust only the main server's certificate; switching it off would cut them off." },
    { n: 30, release: "1.8", name: "Updates that include libraries", why: "Part of how updates are made, not something the screens do." },
];
export const featureSettingKey = (f) => f.setting ?? `feature.${f.key}`;
export const featureByKey = (key) => FEATURES.find((f) => f.key === key);
